INSERT INTO `wp_options` VALUES (318039,'_transient_ctf__PaulAversano3','[{\"user\":{\"name\":\"Paul Aversano\",\"description\":\"Global Practice Leader, @alvarezmarsal Transaction Advisory Group; BoD @PowerPlayNYC @answerthecall; Enjoys family & golf; AKA #006; Posts are my own views.\",\"statuses_count\":7742,\"followers_count\":995,\"screen_name\":\"PaulAversano\",\"verified\":false,\"profile_image_url_https\":\"https:\\/\\/pbs.twimg.com\\/profile_images\\/848983432956956674\\/s26MDoI8_normal.jpg\",\"utc_offset\":null},\"text\":\".@PowerPlayNYC CEO @VSantora1 joins me &amp; @AlvarezMarsal\\u2019s @TonyAlvarezIII #IntheBunkerwithAM as our next honored guest, comparing how the #nonprofit organization used to operate to how it\\u2019s running now. Watch the full episode: https:\\/\\/t.co\\/Jyplydu4bQ #PowerPlayNYC #COVID19 \",\"id_str\":\"1326986516598579201\",\"created_at\":\"Thu Nov 12 20:33:34 +0000 2020\",\"retweet_count\":0,\"favorite_count\":2,\"extended_entities\":{\"media\":[{\"media_url_https\":\"https:\\/\\/pbs.twimg.com\\/ext_tw_video_thumb\\/1326986386528940032\\/pu\\/img\\/IYkgNKKsX1Vmc0Wa.jpg\",\"type\":\"video\",\"sizes\":{\"thumb\":{\"w\":150,\"h\":150,\"resize\":\"crop\"},\"medium\":{\"w\":1200,\"h\":675,\"resize\":\"fit\"},\"small\":{\"w\":680,\"h\":383,\"resize\":\"fit\"},\"large\":{\"w\":1280,\"h\":720,\"resize\":\"fit\"}},\"video_info\":{\"variants\":[{\"url\":\"https:\\/\\/video.twimg.com\\/ext_tw_video\\/1326986386528940032\\/pu\\/vid\\/1280x720\\/ojKMre8BIaE9EJfA.mp4?tag=10\"}]}}]},\"entities\":{\"urls\":[{\"expanded_url\":\"https:\\/\\/bit.ly\\/3oTyrsJ\"}]}},{\"user\":{\"name\":\"Paul Aversano\",\"screen_name\":\"PaulAversano\",\"verified\":false,\"profile_image_url_https\":\"https:\\/\\/pbs.twimg.com\\/profile_images\\/848983432956956674\\/s26MDoI8_normal.jpg\",\"utc_offset\":null},\"text\":\"A British Poison Pill for M&amp;A Bankers?  https:\\/\\/t.co\\/56Ietx4c3b\",\"id_str\":\"1326594543937052672\",\"created_at\":\"Wed Nov 11 18:36:00 +0000 2020\",\"retweet_count\":0,\"favorite_count\":0,\"entities\":{\"urls\":[{\"expanded_url\":\"https:\\/\\/www.bloomberg.com\\/view\\/articles\\/2020-11-11\\/new-u-k-national-security-rules-make-investing-in-tech-much-harder\"}]}},{\"user\":{\"name\":\"Paul Aversano\",\"screen_name\":\"PaulAversano\",\"verified\":false,\"profile_image_url_https\":\"https:\\/\\/pbs.twimg.com\\/profile_images\\/848983432956956674\\/s26MDoI8_normal.jpg\",\"utc_offset\":null},\"text\":\"Forever indebted to our brave #veterans. May we always remember to give them the respect and honor they deserve. Thank you for your service! #VeteransDay #VeteransDay2020 \",\"id_str\":\"1326558066008010752\",\"created_at\":\"Wed Nov 11 16:11:03 +0000 2020\",\"retweet_count\":0,\"favorite_count\":3,\"extended_entities\":{\"media\":[{\"media_url_https\":\"https:\\/\\/pbs.twimg.com\\/media\\/Emjhh6xXIAQMvlB.jpg\",\"type\":\"photo\",\"sizes\":{\"medium\":{\"w\":1024,\"h\":512,\"resize\":\"fit\"},\"thumb\":{\"w\":150,\"h\":150,\"resize\":\"crop\"},\"large\":{\"w\":1024,\"h\":512,\"resize\":\"fit\"},\"small\":{\"w\":680,\"h\":340,\"resize\":\"fit\"}}}]}}]','no');
