INSERT INTO `wp_options` VALUES (318037,'_transient_ctf__NIck_Alvarez673','[{\"user\":{\"name\":\"Nick Alvarez\",\"description\":\"Managing Director & National Practice Leader, @alvarezmarsal Private Equity Performance Improvement; Loves good wine, golf & @SoulCycle; Posts are my own views.\",\"statuses_count\":1743,\"followers_count\":434,\"screen_name\":\"NIck_Alvarez67\",\"verified\":false,\"profile_image_url_https\":\"https:\\/\\/pbs.twimg.com\\/profile_images\\/1068226268670427137\\/Yj31hhlV_normal.jpg\",\"utc_offset\":null},\"text\":\"Great reporting, @deeanndurbin_ap #PrivateEquity \",\"id_str\":\"1326959243736518656\",\"created_at\":\"Thu Nov 12 18:45:12 +0000 2020\",\"retweet_count\":0,\"favorite_count\":1,\"quoted_status\":{\"user\":{\"name\":\"AP Business News\",\"screen_name\":\"APBusiness\",\"verified\":true},\"text\":\"Dunkin\' stock soars after the doughnut and coffee chain confirms it\'s held discussions to be taken private by a private equity firm. @deeanndurbin_ap reports https:\\/\\/t.co\\/TSf3watZqK\",\"id_str\":\"1320778443726999552\"},\"entities\":{\"urls\":[{\"expanded_url\":\"https:\\/\\/twitter.com\\/APBusiness\\/status\\/1320778443726999552\"}]}},{\"user\":{\"name\":\"Nick Alvarez\",\"screen_name\":\"NIck_Alvarez67\",\"verified\":false,\"profile_image_url_https\":\"https:\\/\\/pbs.twimg.com\\/profile_images\\/1068226268670427137\\/Yj31hhlV_normal.jpg\",\"utc_offset\":null},\"text\":\"Thank you to Ben Taylor, @alvarezmarsal #PrivateEquity #PerformanceImprovement Group Senior Director, and all of the men &amp; women who bravely fought for our country! To learn more about Ben: https:\\/\\/t.co\\/lDyghggMeo #VeteransDay #ThankYouForYourService \",\"id_str\":\"1326529222790311937\",\"created_at\":\"Wed Nov 11 14:16:27 +0000 2020\",\"retweet_count\":0,\"favorite_count\":3,\"extended_entities\":{\"media\":[{\"media_url_https\":\"https:\\/\\/pbs.twimg.com\\/ext_tw_video_thumb\\/1326529120738684928\\/pu\\/img\\/wDCX4WS_OoXANjG3.jpg\",\"type\":\"video\",\"sizes\":{\"thumb\":{\"w\":150,\"h\":150,\"resize\":\"crop\"},\"medium\":{\"w\":1200,\"h\":675,\"resize\":\"fit\"},\"small\":{\"w\":680,\"h\":383,\"resize\":\"fit\"},\"large\":{\"w\":1280,\"h\":720,\"resize\":\"fit\"}},\"video_info\":{\"variants\":[{\"url\":\"https:\\/\\/video.twimg.com\\/ext_tw_video\\/1326529120738684928\\/pu\\/vid\\/1280x720\\/tpPwOwjBCWrwhhco.mp4?tag=10\"}]}}]},\"entities\":{\"urls\":[{\"expanded_url\":\"https:\\/\\/bit.ly\\/36mDk55\"}]}},{\"user\":{\"name\":\"Nick Alvarez\",\"screen_name\":\"NIck_Alvarez67\",\"verified\":false,\"profile_image_url_https\":\"https:\\/\\/pbs.twimg.com\\/profile_images\\/1068226268670427137\\/Yj31hhlV_normal.jpg\",\"utc_offset\":null},\"text\":\"This weekend, our @alvarezmarsal #PrivateEquity #PerformanceImprovement SDs Toya Asbury &amp; Janette Ramirez are presenting at the @SpelHouse\'s Professional Development Symposium. To register: https:\\/\\/t.co\\/a0L8JTSvHJ #FinancialServices #CareerDevelopment @The_DTCC @UncolorblindCAB \",\"id_str\":\"1326265888253894656\",\"created_at\":\"Tue Nov 10 20:50:03 +0000 2020\",\"retweet_count\":0,\"favorite_count\":5,\"extended_entities\":{\"media\":[{\"media_url_https\":\"https:\\/\\/pbs.twimg.com\\/media\\/EmfXy8JXEAI9eZs.jpg\",\"type\":\"photo\",\"sizes\":{\"thumb\":{\"w\":150,\"h\":150,\"resize\":\"crop\"},\"large\":{\"w\":1024,\"h\":512,\"resize\":\"fit\"},\"small\":{\"w\":680,\"h\":340,\"resize\":\"fit\"},\"medium\":{\"w\":1024,\"h\":512,\"resize\":\"fit\"}}}]},\"entities\":{\"urls\":[{\"expanded_url\":\"https:\\/\\/bit.ly\\/3kamNWN\"}]}}]','no');
