INSERT INTO `wp_options` VALUES (318041,'_transient_ctf__Ernie_R_Perez3','[{\"user\":{\"name\":\"Ernie Perez\",\"description\":\"Global Practice Leader, @alvarezmarsal Taxand;Transaction Advisory Tax, Domestic\\/Cross-Border Acquisitions, Divestitures, Reorgs @universityofga @miamilawschool\",\"statuses_count\":2420,\"followers_count\":266,\"screen_name\":\"Ernie_R_Perez\",\"verified\":false,\"profile_image_url_https\":\"https:\\/\\/pbs.twimg.com\\/profile_images\\/1288528818320355328\\/eLydngTC_normal.jpg\",\"utc_offset\":null},\"text\":\"I\\u2019m honored to have Tom Ewigleben &amp; Josh Din join our @AlvarezMarsal #Taxand team as Senior Directors, enhancing our firm\\u2019s transformation #tax service offerings. #WelcometotheTeam, Tom &amp; Josh! For more on both #TaxProfessionals: https:\\/\\/t.co\\/7bX5ZCC7kR #NewHire @ClatworthyJason \",\"id_str\":\"1326996994200662025\",\"created_at\":\"Thu Nov 12 21:15:12 +0000 2020\",\"retweet_count\":0,\"favorite_count\":0,\"extended_entities\":{\"media\":[{\"media_url_https\":\"https:\\/\\/pbs.twimg.com\\/ext_tw_video_thumb\\/1326996958762905605\\/pu\\/img\\/alittyG_hHPU8z6S.jpg\",\"type\":\"video\",\"sizes\":{\"thumb\":{\"w\":150,\"h\":150,\"resize\":\"crop\"},\"medium\":{\"w\":1200,\"h\":675,\"resize\":\"fit\"},\"small\":{\"w\":680,\"h\":383,\"resize\":\"fit\"},\"large\":{\"w\":1280,\"h\":720,\"resize\":\"fit\"}},\"video_info\":{\"variants\":[{\"url\":\"https:\\/\\/video.twimg.com\\/ext_tw_video\\/1326996958762905605\\/pu\\/vid\\/640x360\\/icnoGnd4zgymzhW1.mp4?tag=10\"}]}}]},\"entities\":{\"urls\":[{\"expanded_url\":\"https:\\/\\/bit.ly\\/2JG5vEE\"}]}},{\"user\":{\"name\":\"Ernie Perez\",\"screen_name\":\"Ernie_R_Perez\",\"verified\":false,\"profile_image_url_https\":\"https:\\/\\/pbs.twimg.com\\/profile_images\\/1288528818320355328\\/eLydngTC_normal.jpg\",\"utc_offset\":null},\"text\":\"Our @AlvarezMarsal #Taxand team emphasizes the importance of preparing for uncertainty when it comes to #bankruptcy through pre-petition planning &amp; strategic First Day #TaxMotions. Read more: https:\\/\\/t.co\\/Y2jXUYNcfN #TaxAdvisory #TaxMotion #TaxLaw \",\"id_str\":\"1326895043823738880\",\"created_at\":\"Thu Nov 12 14:30:05 +0000 2020\",\"retweet_count\":0,\"favorite_count\":0,\"extended_entities\":{\"media\":[{\"media_url_https\":\"https:\\/\\/pbs.twimg.com\\/media\\/EmoUAnvW4AAWHpe.jpg\",\"type\":\"photo\",\"sizes\":{\"large\":{\"w\":1024,\"h\":512,\"resize\":\"fit\"},\"thumb\":{\"w\":150,\"h\":150,\"resize\":\"crop\"},\"medium\":{\"w\":1024,\"h\":512,\"resize\":\"fit\"},\"small\":{\"w\":680,\"h\":340,\"resize\":\"fit\"}}}]},\"entities\":{\"urls\":[{\"expanded_url\":\"https:\\/\\/bit.ly\\/3k7xSIl\"}]}},{\"user\":{\"name\":\"Ernie Perez\",\"screen_name\":\"Ernie_R_Perez\",\"verified\":false,\"profile_image_url_https\":\"https:\\/\\/pbs.twimg.com\\/profile_images\\/1288528818320355328\\/eLydngTC_normal.jpg\",\"utc_offset\":null},\"text\":\"Saluting our heroes today - thank you for all you\\u2019ve done for our country. #VeteransDay2020 \",\"id_str\":\"1326553796940500992\",\"created_at\":\"Wed Nov 11 15:54:06 +0000 2020\",\"retweet_count\":0,\"favorite_count\":0,\"extended_entities\":{\"media\":[{\"media_url_https\":\"https:\\/\\/pbs.twimg.com\\/media\\/EmjdpQRU4AU1W33.jpg\",\"type\":\"photo\",\"sizes\":{\"medium\":{\"w\":1024,\"h\":512,\"resize\":\"fit\"},\"small\":{\"w\":680,\"h\":340,\"resize\":\"fit\"},\"thumb\":{\"w\":150,\"h\":150,\"resize\":\"crop\"},\"large\":{\"w\":1024,\"h\":512,\"resize\":\"fit\"}}}]}}]','no');
