INSERT INTO `wp_postmeta` VALUES (4646,640,'header-title','Icici Bank Registers the First Case Under the Bankruptcy Code');
INSERT INTO `wp_postmeta` VALUES (4647,640,'_header-title','field_5891147bd81fc');
INSERT INTO `wp_postmeta` VALUES (4648,640,'header-sub-title','');
