INSERT INTO `wp_postmeta` VALUES (12781,1437,'tl-post-header','Rising Tides: Continued Growth In Financial Services M&A Activity');
INSERT INTO `wp_postmeta` VALUES (12779,1437,'header-sub-title','A&M’s Transaction Advisory Financial Industry Group practice is comprised of seasoned deal professionals across all financial services sectors as well as seasoned global leaders of financial institutions. We bring a deep technical and operational understanding to our engagements in the financial services industry.');
