INSERT INTO `wp_postmeta` VALUES (94896,2644,'_yt','field_5ea205b00cc00');
INSERT INTO `wp_postmeta` VALUES (94897,2644,'excerpt','In the fourth episode of our “In The Bunker with A&M” series, Alvarez & Marsal Global Transaction Advisory Group Global Practice Leader Paul Aversano and European Practice Leader Antonio Alvarez III are joined by Cornell University Johnson Graduate School of Management’s Anne & Elmer Lindseth Dean & Professor of Accounting, Mark W. Nelson and Drew Pascarella, Associate Dean for MBA Programs & Senior Lecturer of Finance, to give their perspective on how COVID-19 and the current sociocultural situation have impacted academia especially their faculty & students. Both based in Ithaca, NY, Mark & Drew add valuable insights regarding the importance of human connectivity, the graduates entering the workforce in an uncertain economy, future leadership, and both A&M and Cornell University’s approaches to diversity amidst the protests and the global movement against racism. ');
INSERT INTO `wp_postmeta` VALUES (94898,2644,'_excerpt','field_5ea2045f6319b');
