INSERT INTO `wp_wfissues` VALUES (12942,1605134867,1605134867,'new','wfPluginAbandoned',50,'25471061f9dbfa14096a31860660d678','25471061f9dbfa14096a31860660d678','The Plugin \"Countdown\" appears to be abandoned (updated January 27, 2012, tested to WP 3.2.1).','It was last updated 8 years 9 months ago and tested up to WordPress 3.2.1. Plugins can be removed from wordpress.org for various reasons. This can include benign issues like a plugin author discontinuing development or moving the plugin distribution to their own site, but some might also be due to security issues. In any case, future updates may or may not be available, so it is worth investigating the cause and deciding whether to temporarily or permanently replace or remove the plugin. <a href=\"https://www.wordfence.com/help/?query=scan-result-plugin-abandoned\" target=\"_blank\" rel=\"noopener noreferrer\">Get more information.</a>','a:20:{s:4:\"name\";s:9:\"Countdown\";s:4:\"slug\";s:9:\"countdown\";s:7:\"version\";s:3:\"0.2\";s:6:\"author\";s:52:\"<a href=\"http://studio.bloafer.com/\">Kerry James</a>\";s:14:\"author_profile\";s:38:\"https://profiles.wordpress.org/bloafer\";s:8:\"requires\";s:5:\"3.1.3\";s:6:\"tested\";s:5:\"3.2.1\";s:12:\"requires_php\";b:0;s:13:\"compatibility\";a:0:{}s:11:\"num_ratings\";i:1;s:15:\"support_threads\";i:0;s:24:\"support_threads_resolved\";i:0;s:12:\"last_updated\";s:21:\"2012-01-27 8:48pm GMT\";s:8:\"homepage\";s:54:\"http://studio.bloafer.com/wordpress-plugins/countdown/\";s:13:\"download_link\";s:52:\"https://downloads.wordpress.org/plugin/countdown.zip\";s:12:\"contributors\";a:0:{}s:11:\"dateUpdated\";s:16:\"January 27, 2012\";s:9:\"abandoned\";b:1;s:10:\"vulnerable\";b:0;s:5:\"wpURL\";s:39:\"https://wordpress.org/plugins/countdown\";}');
