INSERT INTO `wp_wfissues` VALUES (12951,1605199618,1605199618,'new','wfPluginUpgrade',50,'2406e6f99b1c585476cbcedf0c381dd6','2406e6f99b1c585476cbcedf0c381dd6','The Plugin \"Akismet Anti-Spam\" needs an upgrade (4.1.3 -> 4.1.7).','You need to upgrade \"Akismet Anti-Spam\" to the newest version to ensure you have any security fixes the developer has released.','a:16:{s:4:\"Name\";s:17:\"Akismet Anti-Spam\";s:9:\"PluginURI\";s:20:\"https://akismet.com/\";s:7:\"Version\";s:5:\"4.1.3\";s:11:\"Description\";s:363:\"Used by millions, Akismet is quite possibly the best way in the world to <strong>protect your blog from spam</strong>. It keeps your site protected even while you sleep. To get started: activate the Akismet plugin and then go to your Akismet Settings page to set up your API key. <cite>By <a href=\"https://automattic.com/wordpress-plugins/\">Automattic</a>.</cite>\";s:6:\"Author\";s:66:\"<a href=\"https://automattic.com/wordpress-plugins/\">Automattic</a>\";s:9:\"AuthorURI\";s:41:\"https://automattic.com/wordpress-plugins/\";s:10:\"TextDomain\";s:7:\"akismet\";s:10:\"DomainPath\";s:0:\"\";s:7:\"Network\";b:0;s:5:\"Title\";s:52:\"<a href=\"https://akismet.com/\">Akismet Anti-Spam</a>\";s:10:\"AuthorName\";s:10:\"Automattic\";s:10:\"pluginFile\";s:69:\"/home/eo044zl56xul/public_html/wp-content/plugins/akismet/akismet.php\";s:10:\"newVersion\";s:5:\"4.1.7\";s:4:\"slug\";s:7:\"akismet\";s:5:\"wpURL\";s:37:\"https://wordpress.org/plugins/akismet\";s:10:\"vulnerable\";b:0;}');
INSERT INTO `wp_wfissues` VALUES (12952,1605199618,1605199618,'new','wfPluginUpgrade',50,'13671862999ad889dde03b5f8018adb3','13671862999ad889dde03b5f8018adb3','The Plugin \"Carousel Horizontal Posts Content Slider\" needs an upgrade (3.2.5 -> 3.2.7).','You need to upgrade \"Carousel Horizontal Posts Content Slider\" to the newest version to ensure you have any security fixes the developer has released.','a:16:{s:4:\"Name\";s:40:\"Carousel Horizontal Posts Content Slider\";s:9:\"PluginURI\";s:70:\"http://wordpress.org/plugins/carousel-horizontal-posts-content-slider/\";s:7:\"Version\";s:5:\"3.2.5\";s:11:\"Description\";s:118:\"A simple horizontal posts content slider plugin. <cite>By <a href=\"http://www.weaveapps.com\">subhansanjaya</a>.</cite>\";s:6:\"Author\";s:52:\"<a href=\"http://www.weaveapps.com\">subhansanjaya</a>\";s:9:\"AuthorURI\";s:24:\"http://www.weaveapps.com\";s:10:\"TextDomain\";s:40:\"carousel-horizontal-posts-content-slider\";s:10:\"DomainPath\";s:0:\"\";s:7:\"Network\";b:0;s:5:\"Title\";s:125:\"<a href=\"http://wordpress.org/plugins/carousel-horizontal-posts-content-slider/\">Carousel Horizontal Posts Content Slider</a>\";s:10:\"AuthorName\";s:13:\"subhansanjaya\";s:10:\"pluginFile\";s:100:\"/home/eo044zl56xul/public_html/wp-content/plugins/carousel-horizontal-posts-content-slider/chpcs.php\";s:10:\"newVersion\";s:5:\"3.2.7\";s:4:\"slug\";s:40:\"carousel-horizontal-posts-content-slider\";s:5:\"wpURL\";s:70:\"https://wordpress.org/plugins/carousel-horizontal-posts-content-slider\";s:10:\"vulnerable\";b:0;}');
INSERT INTO `wp_wfissues` VALUES (12953,1605199618,1605199618,'new','wfPluginUpgrade',50,'a516b19320f6eaf9c196e6e35f3ab987','a516b19320f6eaf9c196e6e35f3ab987','The Plugin \"Clef\" needs an upgrade (2.3.4 -> 2.6.4).','You need to upgrade \"Clef\" to the newest version to ensure you have any security fixes the developer has released.','a:16:{s:4:\"Name\";s:4:\"Clef\";s:9:\"PluginURI\";s:42:\"http://wordpress.org/extend/plugins/wpclef\";s:7:\"Version\";s:5:\"2.3.4\";s:11:\"Description\";s:175:\"Clef lets you log in and register on your WordPress site using only your phone — forget your usernames and passwords. <cite>By <a href=\"https://getclef.com\">Clef</a>.</cite>\";s:6:\"Author\";s:38:\"<a href=\"https://getclef.com\">Clef</a>\";s:9:\"AuthorURI\";s:19:\"https://getclef.com\";s:10:\"TextDomain\";s:6:\"wpclef\";s:10:\"DomainPath\";s:0:\"\";s:7:\"Network\";b:0;s:5:\"Title\";s:61:\"<a href=\"http://wordpress.org/extend/plugins/wpclef\">Clef</a>\";s:10:\"AuthorName\";s:4:\"Clef\";s:10:\"pluginFile\";s:67:\"/home/eo044zl56xul/public_html/wp-content/plugins/wpclef/wpclef.php\";s:10:\"newVersion\";s:5:\"2.6.4\";s:4:\"slug\";s:6:\"wpclef\";s:5:\"wpURL\";s:36:\"https://wordpress.org/plugins/wpclef\";s:10:\"vulnerable\";b:0;}');
INSERT INTO `wp_wfissues` VALUES (12915,1605134788,1605134788,'new','skippedPaths',25,'6fd0d290b978eab8027e6b79501ac149','6fd0d290b978eab8027e6b79501ac149','3 paths were skipped for the malware scan due to scan settings','The option \"Scan files outside your WordPress installation\" is off by default, which means 3 paths and their file(s) will not be scanned for malware or unauthorized changes. To continue skipping these paths, you may ignore this issue. Or to start scanning them, enable the option and subsequent scans will include them. Some paths may not be necessary to scan, so this is optional. <a href=\"https://www.wordfence.com/help/?query=scan-result-skipped-paths\" target=\"_blank\" rel=\"noopener noreferrer\">Learn More</a><br><br>The paths skipped are ~/_, ~/eblast, and ~/pdf','a:0:{}');
